function draw() {
  // clear
  ctx.clearRect(0,0,width,height);
  // background
  ctx.fillStyle = '#001';
  ctx.fillRect(0,0,width,height);
  // stars
  ctx.fillStyle = '#fff';
  for (const s of stars) {
    ctx.beginPath();
    ctx.arc(s.x, s.y, s.r, 0, Math.PI*2);
    ctx.fill();
  }
  // particles (explosions)
  for (let i = particles.length - 1; i >= 0; i--) {
    const p = particles[i];
    p.x += p.dx;
    p.y += p.dy;
    p.life++;
    const alpha = 1 - p.life / p.maxLife;
    ctx.fillStyle = `rgba(255,165,0,${alpha})`;
    ctx.fillRect(p.x, p.y, 2, 2);
    if (p.life >= p.maxLife) particles.splice(i,1);
  }
  // ship triangle with gradient
  const grad = ctx.createLinearGradient(ship.x, ship.y, ship.x, ship.y + ship.h);
  grad.addColorStop(0, '#0f0');
  grad.addColorStop(1, '#080');
  ctx.fillStyle = grad;
  ctx.beginPath();
  ctx.moveTo(ship.x, ship.y + ship.h);
  ctx.lineTo(ship.x + ship.w / 2, ship.y);
  ctx.lineTo(ship.x + ship.w, ship.y + ship.h);
  ctx.closePath();
  ctx.fill();
  // bullets
  ctx.fillStyle = '#ff0';
  bullets.forEach(b => ctx.fillRect(b.x, b.y, b.w, b.h));
  // asteroids with radial gradient
  asteroids.forEach(a => {
    const rad = ctx.createRadialGradient(a.x + a.w/2, a.y + a.h/2, a.w/4, a.x + a.w/2, a.y + a.h/2, a.w/2);
    rad.addColorStop(0, '#aaa');
    rad.addColorStop(1, '#555');
    ctx.fillStyle = rad;
    ctx.fillRect(a.x, a.y, a.w, a.h);
  });
  // game over overlay
  if (gameOver) {
    ctx.fillStyle = 'rgba(0,0,0,0.5)';
    ctx.fillRect(0,0,width,height);
    ctx.fillStyle = '#f00';
    ctx.font = '30px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('Game Over', width/2, height/2);
  }
}

